<?php
require_once "config/database.php";require_once "includes/functions.php";require_login();$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT o.*,u.name rider_name,a.address,a.phone FROM orders o JOIN delivery_addresses a ON a.id=o.delivery_address_id LEFT JOIN users u ON u.id=o.rider_id WHERE o.id=? AND o.user_id=?");$s->execute([$id,$_SESSION['user']['id']]);$o=$s->fetch();if(!$o)die("Order not found.");
$steps=['Pending','Confirmed','Preparing','Ready for Pickup','Assigned to Rider','Picked Up','Out for Delivery','Delivered'];$idx=array_search($o['order_status'],$steps);$idx=$idx===false?-1:$idx;
$page_title="Track Order";include "includes/header.php";?><div class="container py-5"><h2>Track <?=e($o['order_number'])?></h2><div class="card p-4 shadow-sm mt-3"><p><strong>Status:</strong> <span class="badge text-bg-danger"><?=e($o['order_status'])?></span></p><?php foreach($steps as $i=>$st):?><div class="status-step <?=$i<=$idx?'active':''?>"><strong><?=$i<=$idx?'✓':'○'?> <?=e($st)?></strong></div><?php endforeach;?><hr><p><strong>Delivery address:</strong><br><?=nl2br(e($o['address']))?></p><?php if($o['rider_name']):?><p><strong>Rider:</strong> <?=e($o['rider_name'])?></p><?php endif;?></div></div><?php include "includes/footer.php"; ?>